import{_ as t,o as a,c as o,ag as n}from"./chunks/framework.8tqBsFWt.js";const h=JSON.parse('{"title":"User Disambiguation","description":"","frontmatter":{},"headers":[],"relativePath":"reference/workflows/disambiguation.md","filePath":"reference/workflows/disambiguation.md"}'),r={name:"reference/workflows/disambiguation.md"};function s(i,e,d,l,c,u){return a(),o("div",null,[...e[0]||(e[0]=[n(`<h1 id="user-disambiguation" tabindex="-1">User Disambiguation <a class="header-anchor" href="#user-disambiguation" aria-label="Permalink to &quot;User Disambiguation&quot;">​</a></h1><p>How VERA identifies a user when a tool needs a target person.</p><hr><h2 id="resolution-order" tabindex="-1">Resolution order <a class="header-anchor" href="#resolution-order" aria-label="Permalink to &quot;Resolution order&quot;">​</a></h2><p>When a tool receives a user reference, VERA resolves it in this order:</p><ol><li><strong>Slack mention</strong> (<code>user_slack_id</code> or <code>pm_slack_id</code>) — always resolved via mention-matching, never name-matching</li><li><strong>Internal ID</strong> (<code>user_id</code>) — direct integer lookup</li><li><strong>Name string</strong> (<code>user_name</code>, <code>pm_name</code>, <code>vendor_name</code>, <code>person</code>, <code>current_name</code>) — exact-match or dialing menu</li></ol><hr><h2 id="mention-forms-rule-a-—-bulletproof" tabindex="-1">Mention forms (Rule A — bulletproof) <a class="header-anchor" href="#mention-forms-rule-a-—-bulletproof" aria-label="Permalink to &quot;Mention forms (Rule A — bulletproof)&quot;">​</a></h2><p>When the message contains any of the following, VERA extracts the Slack user ID directly and looks up the user without any name matching:</p><table tabindex="0"><thead><tr><th>Form</th><th>Example</th></tr></thead><tbody><tr><td>Standard mention</td><td><code>&lt;@U0ADQ6UAVKR&gt;</code></td></tr><tr><td>Mention with label</td><td><code>&lt;@U0ADQ6UAVKR|alice&gt;</code></td></tr><tr><td>Bare Slack user ID</td><td><code>U0ADQ6UAVKR</code></td></tr><tr><td>Markdown profile link</td><td><code>[@alice](https://workspace.slack.com/team/U0ADQ6UAVKR)</code></td></tr><tr><td>Bare profile URL</td><td><code>https://workspace.slack.com/team/U0ADQ6UAVKR</code></td></tr><tr><td>At-handle</td><td><code>@alice</code> (requires Slack API lookup)</td></tr><tr><td>Email mention</td><td><code>&lt;mailto:alice@example.com|alice@example.com&gt;</code> (requires Slack API lookup)</td></tr></tbody></table><p>If the Slack user ID is extracted but that person is not registered in VERA, the error is exact: &quot;that Slack user (UXXXXXXXX) isn&#39;t registered in VERA yet.&quot; VERA never falls back to a name search.</p><hr><h2 id="name-based-resolution-rule-b-—-exact-or-menu" tabindex="-1">Name-based resolution (Rule B — exact or menu) <a class="header-anchor" href="#name-based-resolution-rule-b-—-exact-or-menu" aria-label="Permalink to &quot;Name-based resolution (Rule B — exact or menu)&quot;">​</a></h2><p>When a plain name is provided (e.g. <code>user_name: &quot;Alice&quot;</code>), VERA applies a two-step process:</p><p><strong>Step 1 — Exact match (case-insensitive)</strong> If exactly one user&#39;s name matches the query, VERA proceeds without confirmation. If two users have the same name, a dialing menu is shown for both.</p><p><strong>Step 2 — Fuzzy candidates (always a menu, never auto-pick)</strong> If no exact match is found, VERA collects candidates via:</p><ul><li>Substring match (query contains stored name or vice versa)</li><li>Word-overlap match (any word in the query matches a word in a stored name)</li><li>Levenshtein distance ≤ 2 and ≤ 30% of the longer string</li></ul><p>Even if only one fuzzy candidate is found, VERA shows a numbered menu. It never auto-picks a near-miss.</p><hr><h2 id="dialing-menus" tabindex="-1">Dialing menus <a class="header-anchor" href="#dialing-menus" aria-label="Permalink to &quot;Dialing menus&quot;">​</a></h2><p>When VERA cannot auto-resolve a name, it returns a numbered list:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Multiple matches for &quot;Al&quot;. Reply with the number:</span></span>
<span class="line"><span></span></span>
<span class="line"><span>1. Alice (owner)</span></span>
<span class="line"><span>2. Alan (user)</span></span></code></pre></div><p>Reply with the number (e.g. <code>1</code>). VERA resumes the original action immediately — no re-paraphrase, no re-confirmation.</p><p>The pending action expires after 10 minutes. If you send any other message in the meantime, the pending action is discarded.</p><hr><h2 id="no-match" tabindex="-1">No match <a class="header-anchor" href="#no-match" aria-label="Permalink to &quot;No match&quot;">​</a></h2><p>If no candidates are found at all, VERA returns:</p><blockquote><p>❌ Failed: no user named &quot;Zephyr&quot; exists. Check the spelling or add them first.</p></blockquote><p>Use <code>list users</code> to see the current roster.</p>`,29)])])}const p=t(r,[["render",s]]);export{h as __pageData,p as default};
